import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
import { FlyProvider } from './fly-provider.mjs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const fly = new FlyProvider();
const receiptFile = 'fly-workspace.json';
const workspace = 'ws-ada-7f3c9e2a41b8';
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receiptFile, 'utf8'));
  assert.deepEqual([...await fly.running()], [workspace], 'the resumed workspace is the one running sandbox');
  const machine = await fly.api('GET', `/apps/${fly.app}/machines/${saved.machine}`);
  assert.equal(machine.state, 'started');
  assert.equal(machine.config.mounts[0].volume, saved.volume);
  assert.equal(machine.instance_id, saved.instance);
  const volumes = await fly.api('GET', `/apps/${fly.app}/volumes`);
  assert.deepEqual(volumes.map((v) => [v.id, v.name, v.state, v.attached_machine_id]), [[saved.volume, 'ws_ada', 'created', saved.machine]]);
  console.log(JSON.stringify({ retained: true, machine: machine.id, state: machine.state, volume: saved.volume }));
} else {
  // the World's operator enrolls its fake machine pool: it records each run and runs no image
  const twin = process.env.FLY_TWIN_URL;
  if (!twin) throw new Error('The World names no Fly twin URL.');
  const enrolled = await fetch(twin + '/_twin/machine-pool', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ kind: 'fake' }) });
  assert.equal(enrolled.status, 201, await enrolled.text());
  // Substrate allocates Ada's workspace, pauses it overnight and resumes it (manager.ts's four calls)
  const started = await fly.start({ id: workspace, token: 'sbx_ada_workspace', volume: 'ws_ada', limits: { cpus: 1, memoryBytes: 512 * 1024 * 1024 } });
  assert.match(started.name, /^[0-9a-f]{14}$/, 'a machine id is fourteen hex digits');
  assert.match(started.url, /^http:\/\/127\.0\.0\.1:\d+$/, 'the workspace is reached at the port the World published');
  const first = await fly.api('GET', `/apps/${fly.app}/machines/${started.name}`);
  assert.equal(first.state, 'started');
  assert.equal(first.config.guest.memory_mb, 512);
  assert.equal(first.config.metadata['volter.substrate.sandbox'], workspace);
  await fly.pause(started);
  const paused = await fly.api('GET', `/apps/${fly.app}/machines/${started.name}`);
  assert.equal(paused.state, 'stopped');
  assert.equal(paused.twin_local_ports, undefined, 'a stopped machine publishes no port');
  assert.deepEqual([...await fly.running()], []);
  const resumed = await fly.resume(started);
  assert.match(resumed.url, /^http:\/\/127\.0\.0\.1:\d+$/);
  const again = await fly.api('GET', `/apps/${fly.app}/machines/${started.name}`);
  assert.equal(again.state, 'started');
  assert.notEqual(again.instance_id, first.instance_id, 'each start is a new instance');
  assert.deepEqual([...await fly.running()], [workspace]);
  fly.close();
  writeFileSync(receiptFile, JSON.stringify({ machine: started.name, volume: again.config.mounts[0].volume, instance: again.instance_id }) + '\n');
  console.log(JSON.stringify({ started: started.name, url: started.url, resumed: resumed.url, instance: again.instance_id }));
}

