// Substrate's Fly Machines provider (volter-ai/browser-substrate 3116b2e3f713, packages/sandboxes/src/fly-provider.ts),
// its TypeScript types removed and nothing else changed.
import { spawn } from "node:child_process";

export class FlyProvider {
  pauseMode = "restart-processes";
  proxies = new Map();

  constructor({
    apiUrl = process.env.FLY_API_HOSTNAME ?? "https://api.machines.dev",
    token = process.env.FLY_API_TOKEN,
    app = process.env.FLY_APP ?? "substrate-sandboxes",
    org = process.env.FLY_ORG ?? "personal",
    region = process.env.FLY_REGION ?? "iad",
    image = process.env.FLY_IMAGE ?? "substrate-node-host:local",
    label = "volter.substrate.sandbox",
    access,
  } = {}) {
    if (!token) throw new Error("FLY_API_TOKEN is required.");
    this.apiUrl = apiUrl.replace(/\/$/, "");
    this.token = token;
    this.app = app;
    this.org = org;
    this.region = region;
    this.image = image;
    this.label = label;
    const configured = process.env.FLY_ACCESS === "direct" ? "direct" : process.env.FLY_ACCESS === "proxy" ? "proxy" : undefined;
    this.access = access ?? configured ?? (/api\.machines\.dev/.test(this.apiUrl) ? "proxy" : "direct");
  }

  async api(method, path, body) {
    const response = await fetch(`${this.apiUrl}/v1${path}`, {
      method,
      headers: { authorization: `Bearer ${this.token}`, ...(body !== undefined ? { "content-type": "application/json" } : {}) },
      ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
    });
    const text = await response.text();
    if (!response.ok) throw new Error(`Fly ${method} ${path} -> ${response.status} ${text}`);
    return (text ? JSON.parse(text) : undefined);
  }

  async ensureApp() {
    try { await this.api("GET", `/apps/${this.app}`); }
    catch { await this.api("POST", "/apps", { app_name: this.app, org_slug: this.org }); }
  }

  async ensureVolume(name) {
    const volumes = await this.api("GET", `/apps/${this.app}/volumes`);
    // A deleted volume lingers as pending_destroy; only a created one is mountable.
    return volumes.find((volume) => volume.name === name && volume.state === "created")
      ?? this.api("POST", `/apps/${this.app}/volumes`, { name, region: this.region, size_gb: 1 });
  }

  async url(machine) {
    const local = (machine.twin_local_ports ?? []).find((entry) => entry.internal === 8787);
    if (local) return `http://127.0.0.1:${local.host}`;
    if (this.access !== "proxy") return `http://[${machine.private_ip ?? ""}]:8787`;
    const existing = this.proxies.get(machine.id);
    if (existing) return existing.url;
    const port = 20_000 + Math.floor(Math.random() * 20_000);
    const child = spawn("fly", ["proxy", `${port}:8787`, machine.private_ip ?? "", "-a", this.app], { stdio: ["ignore", "ignore", "pipe"] });
    child.stderr?.on("data", () => undefined);
    child.on("error", () => this.proxies.delete(machine.id));
    const proxy = { child, url: `http://127.0.0.1:${port}` };
    this.proxies.set(machine.id, proxy);
    return proxy.url;
  }

  closeProxy(machineId) {
    const proxy = this.proxies.get(machineId);
    if (!proxy) return;
    proxy.child.kill("SIGTERM");
    this.proxies.delete(machineId);
  }

  async start({ id, token, image = this.image, limits = {}, volume }) {
    await this.ensureApp();
    const mounts = volume ? [{ volume: (await this.ensureVolume(volume)).id, path: "/workspace" }] : [];
    const created = await this.api("POST", `/apps/${this.app}/machines`, {
      name: `sandbox-${id.slice(0, 12)}`,
      region: this.region,
      config: {
        image,
        env: { SUBSTRATE_ROOT: "/", SUBSTRATE_TOKEN: token, PORT: "8787", HOST: "::" },
        services: [{ protocol: "tcp", internal_port: 8787, ports: [{ port: 8787 }] }],
        // Fly sizes guest memory in 256 MiB steps.
        guest: { cpu_kind: "shared", cpus: Math.max(1, Math.ceil(limits.cpus ?? 1)), memory_mb: Math.max(256, Math.ceil((limits.memoryBytes ?? 256 * 1024 * 1024) / (256 * 1_048_576)) * 256) },
        metadata: { [this.label]: id },
        mounts,
      },
    });
    await this.api("GET", `/apps/${this.app}/machines/${created.id}/wait?state=started&timeout=60`);
    const machine = await this.api("GET", `/apps/${this.app}/machines/${created.id}`);
    return { name: created.id, url: await this.url(machine) };
  }

  async pause({ name }) {
    await this.api("POST", `/apps/${this.app}/machines/${name}/stop`);
    await this.api("GET", `/apps/${this.app}/machines/${name}/wait?state=stopped&timeout=60`);
  }

  async resume({ name }) {
    // A restarted machine is a new guest; the old forward is stale, so rebuild it.
    this.closeProxy(name);
    await this.api("POST", `/apps/${this.app}/machines/${name}/start`);
    await this.api("GET", `/apps/${this.app}/machines/${name}/wait?state=started&timeout=60`);
    return { url: await this.url(await this.api("GET", `/apps/${this.app}/machines/${name}`)) };
  }

  async stop({ name }) {
    this.closeProxy(name);
    try { await this.api("DELETE", `/apps/${this.app}/machines/${name}?force=true`); } catch { /* already gone */ }
  }

  close() { for (const id of [...this.proxies.keys()]) this.closeProxy(id); }

  async running() {
    const machines = await this.api("GET", `/apps/${this.app}/machines`);
    return new Set(machines.filter((machine) => machine.state === "started").map((machine) => machine.config?.metadata?.[this.label]).filter((value) => Boolean(value)));
  }

  async removeVolume(name) {
    const volumes = await this.api("GET", `/apps/${this.app}/volumes`);
    for (const volume of volumes.filter((candidate) => candidate.name === name)) {
      try { await this.api("DELETE", `/apps/${this.app}/volumes/${volume.id}`); } catch { /* gone */ }
    }
  }
}
